CREATE TABLE purchase_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), supplier_id uuid NOT NULL, po_number text NOT NULL, order_date date NOT NULL, expected_delivery_date date, delivered_at date, total_amount numeric(18,2) NOT NULL DEFAULT 0, status text NOT NULL CHECK(status IN ('DRAFT','PENDING','PARTIAL','DELIVERED','CANCELLED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (organization_id,supplier_id) REFERENCES suppliers(organization_id,id), UNIQUE(organization_id,po_number), UNIQUE(organization_id,id)); CREATE INDEX purchase_orders_org_supplier_idx ON purchase_orders(organization_id,supplier_id,expected_delivery_date);
CREATE TABLE purchase_order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), purchase_order_id uuid NOT NULL, product_id uuid NOT NULL, quantity numeric(18,3) NOT NULL CHECK(quantity>0), unit_cost numeric(18,2) NOT NULL DEFAULT 0, FOREIGN KEY (organization_id,product_id) REFERENCES products(organization_id,id), FOREIGN KEY (organization_id,purchase_order_id) REFERENCES purchase_orders(organization_id,id)); CREATE INDEX purchase_order_items_org_po_idx ON purchase_order_items(organization_id,purchase_order_id);
